fn rgb_to_hsl(r: u8, g: u8, b: u8) -> (f32, f32, f32) {
    let r = r as f32 / 255.0;
    let g = g as f32 / 255.0;
    let b = b as f32 / 255.0;
    let max = r.max(g).max(b);
    let min = r.min(g).min(b);
    let mut h = 0.0;
    let s = if max == min { 0.0 } else { (max - min) / max };
    let l = (max + min) / 2.0;
    if max != min {
        h = if max == r {
            (g - b) / (max - min) * 60.0
        } else if max == g {
            2.0 + (b - r) / (max - min) * 60.0
        } else {
            4.0 + (r - g) / (max - min) * 60.0
        };
        if h < 0.0 {
            h += 360.0;
        }
    }
    (h, s, l)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_theme_color_from_hex() {
        let color = ThemeColor::from_hex("red".to_string(), "#ff0000".to_string()).unwrap();
        assert_eq!(color.hex, "#ff0000");
        assert_eq!(color.rgb, (255, 0, 0));
    }

    #[test]
    fn test_theme_manager_defaults() {
        let manager = ThemeManager::default();
        assert_eq!(manager.theme_list_count(), 2);
        assert!(manager.active_theme.is_some());
    }

    #[test]
    fn test_set_active_theme() {
        let mut manager = ThemeManager::default();
        assert!(manager.set_active_theme("catppuccin-latte").is_ok());
        assert_eq!(manager.active_theme.as_deref(), Some("catppuccin-latte"));
    }

    #[test]
    fn test_generate_from_wallpaper() {
        let mut manager = ThemeManager::default();
        let name = manager.generate_from_wallpaper("/usr/share/wallpapers/nature.jpg").unwrap();
        assert!(name.starts_with("wallpaper-"));
    }

    #[test]
    fn test_color_count() {
        let manager = ThemeManager::default();
        let theme = manager.get_active_theme().unwrap();
        let total = theme.palette.base8.len() + theme.palette.extended16.len() + theme.palette.full24.len();
        assert_eq!(total, 48); // 8 + 16 + 24 = 48 colors
    }
}